create or replace function nexus_private.workflow_value(body jsonb, item jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$
declare v jsonb;
begin
  if item ? 'tagField' and body #>> string_to_array(item->>'tagField','.') is distinct from item->>'tagValue' then return 'null'::jsonb; end if;
  v:=body #> string_to_array(item->>'bodyField','.');
  return coalesce(v,'null'::jsonb);
end $$;

create or replace function nexus_private.workflow_state(body jsonb, definition jsonb) returns text
language plpgsql immutable set search_path='' as $$
declare v text;
begin
  if not definition ? 'stateField' then return null; end if;
  v:=body->>(definition->>'stateField');
  if definition->>'stateField'='active' then
    if v='true' then return 'active'; elsif v='false' then return 'inactive'; end if;
  end if;
  return v;
end $$;

