    execute format('alter table public.%I enable row level security',tbl);
    execute format('revoke all on public.%I from public,anon,authenticated',tbl);
    execute format('grant select,insert,update,delete on public.%I to service_role',tbl);
  end loop;
  -- Shared projections are mechanically derived without modifying payload JSONB.
  for d in select definition from nexus_private.workflow_manifest where definition->>'storage'='shared' loop
    cols:='row_version=coalesce(row_version,1)';
    for c in select value from jsonb_array_elements(d->'columns') loop
      sql_type:=case c->>'type' when 'integer' then 'bigint' when 'real' then 'double precision' when 'boolean' then 'boolean' when 'json' then 'jsonb' else 'text' end;
      if c->>'type'='json' then cols:=cols||format(',%I=payload #> %L::text[]',c->>'column',string_to_array(c->>'bodyField','.'));
      else cols:=cols||format(',%I=(payload #>> %L::text[])::%s',c->>'column',string_to_array(c->>'bodyField','.'),sql_type); end if;
    end loop;
    execute format('update public.%I set %s where row_version is null',d->>'table',cols);
  end loop;
  for d in select definition from nexus_private.workflow_manifest loop
    tbl:=d->>'table';
    for child in select value from jsonb_array_elements(d->'normalizedChildren') loop
      execute format('create table if not exists public.%I(%I text not null references public.%I(id) on delete no action deferrable initially deferred,%I text not null references public.%I(id) on delete no action deferrable initially deferred,primary key(%I,%I))',child->>'table',child->>'parentIdColumn',tbl,child->>'childIdColumn',child->>'target',child->>'parentIdColumn',child->>'childIdColumn');
      execute format('create unique index if not exists %I on public.%I(%I,%I)',child->>'uniqueName',child->>'table',child->>'parentIdColumn',child->>'childIdColumn');
      execute format('create index if not exists %I on public.%I(%I,%I)',(child->>'table')||'_target_lookup',child->>'table',child->>'childIdColumn',child->>'parentIdColumn');
      execute format('alter table public.%I enable row level security',child->>'table');
      execute format('revoke all on public.%I from public,anon,authenticated,service_role',child->>'table');
      execute format('grant select on public.%I to service_role',child->>'table');
    end loop;
    for f in select value from jsonb_array_elements(d->'foreignKeys') loop
      colname:='wf_'||tbl||'_'||(f->>'column')||'_fk';
      if not exists(select 1 from pg_catalog.pg_constraint where conrelid=format('public.%I',tbl)::regclass and conname=left(colname,63)) then
        execute format('alter table public.%I add constraint %I foreign key(%I) references public.%I(id) on delete no action deferrable initially deferred',tbl,colname,f->>'column',f->>'target');
      end if;
    end loop;
    if tbl='responsibilities' then execute 'drop index if exists public.responsibilities_open_identity_purpose_unique'; end if;
    for u in select value from jsonb_array_elements(d->'unique') loop
      cols:='';
      for field in select jsonb_array_elements_text(u->'fields') loop
        select x->>'column' into colname from jsonb_array_elements(d->'columns') x where x->>'bodyField'=field;
        if field='id' then colname:='id'; elsif field='rowVersion' then colname:='row_version'; end if;
        if colname is null then raise exception 'Invalid workflow constraint definition' using errcode='22023'; end if;
        cols:=cols||case when cols='' then '' else ',' end||format('%I',colname);
      end loop;
      predicate:=case when d->>'storage'='mixed' then 'workflow_contract_version=2' else 'true' end;
      if coalesce((u->>'openOnly')::boolean,false) then
        select string_agg(quote_literal(value),',') into field from jsonb_array_elements_text(u->'openStates');
        if field is null then raise exception 'Invalid workflow open constraint' using errcode='22023'; end if;
        predicate:=predicate||format(' and nexus_private.workflow_state(%I,%L::jsonb) in (%s)',d->>'bodyColumn',d::text,field);
      end if;
      if predicate='true' then execute format('create unique index if not exists %I on public.%I(%s)',u->>'name',tbl,cols);
      else execute format('create unique index if not exists %I on public.%I(%s) where %s',u->>'name',tbl,cols,predicate); end if;
    end loop;
    for field in select jsonb_array_elements_text(d->'queryFields') loop
      select x->>'column' into colname from jsonb_array_elements(d->'columns') x where x->>'bodyField'=field;
      if colname is not null then execute format('create index if not exists %I on public.%I(%I,id)','wf_'||tbl||'_'||colname||'_lookup',tbl,colname); end if;
    end loop;
  end loop;
  -- Composite business-version FKs are installed after the referenced unique indexes.
  for d in select definition from nexus_private.workflow_manifest loop
    tbl:=d->>'table';
    for f in select value from jsonb_array_elements(d->'foreignKeys') where value->>'requiredContractVersion'='2' loop
      execute format('create unique index if not exists %I on public.%I(id,workflow_contract_version)','workflow_'||(f->>'target')||'_contract_reference_unique',f->>'target');
      colname:='wf_'||tbl||'_'||(f->>'column')||'_contract_fk';
      if not exists(select 1 from pg_catalog.pg_constraint where conrelid=format('public.%I',tbl)::regclass and conname=left(colname,63)) then
        execute format('alter table public.%I add constraint %I foreign key(%I,%I) references public.%I(id,workflow_contract_version) on delete no action deferrable initially deferred',tbl,colname,f->>'column',regexp_replace(f->>'column','_id$','')||'_contract_version',f->>'target');
      end if;
    end loop;
    for f in select value from jsonb_array_elements(d->'compositeForeignKeys') loop
      select string_agg(format('%I',value),',') into cols from jsonb_array_elements_text(f->'columns');
      select string_agg(format('%I',value),',') into predicate from jsonb_array_elements_text(f->'targetColumns');
      colname:='wf_'||tbl||'_'||(f->>'target')||'_business_fk';
      if not exists(select 1 from pg_catalog.pg_constraint where conrelid=format('public.%I',tbl)::regclass and conname=left(colname,63)) then execute format('alter table public.%I add constraint %I foreign key(%s) references public.%I(%s) on delete no action deferrable initially deferred',tbl,colname,cols,f->>'target',predicate); end if;
    end loop;
  end loop;
end $$;

create or replace function nexus_private.workflow_guard() returns trigger
language plpgsql security definer set search_path='' as $$
declare d jsonb; b jsonb; old_b jsonb; row_json jsonb; typed jsonb:='{}'; c jsonb; f jsonb; child jsonb; v jsonb; discriminator jsonb; equality jsonb;
  field text; old_state text; new_state text; target_count integer:=0; protected boolean;
begin
  select definition into strict d from nexus_private.workflow_manifest where table_name=tg_table_name;
  if tg_op='DELETE' then
    if tg_table_name='audit_events' or (tg_table_name='action_executions' and (to_jsonb(old)->'payload'->>'status') in ('verified_success','failed','denied')) then raise exception 'Immutable legacy history' using errcode='23514'; end if;
    if d->>'storage'<>'shared' and (d->>'storage'<>'mixed' or to_jsonb(old)->>'workflow_contract_version'='2') then raise exception 'Workflow history cannot be deleted' using errcode='23514'; end if;
    return old;
  end if;
  row_json:=to_jsonb(new); b:=row_json->(d->>'bodyColumn');
  if jsonb_typeof(b)<>'object' or jsonb_typeof(b->'id')<>'string' or b->>'id' is distinct from new.id then raise exception 'Invalid workflow body identity' using errcode='23514'; end if;
  protected:=d->>'storage'<>'mixed' or coalesce(row_json->>'workflow_contract_version'='2',false);
  if tg_op='UPDATE' then
    old_b:=to_jsonb(old)->(d->>'bodyColumn');
    if d->>'storage'='mixed' and row_json->'workflow_contract_version' is distinct from to_jsonb(old)->'workflow_contract_version' then raise exception 'Immutable workflow marker' using errcode='23514'; end if;
  end if;
  if not protected then
    if tg_op='UPDATE' and (tg_table_name='audit_events' or (tg_table_name='action_executions' and old_b->>'status' in ('verified_success','failed','denied'))) then raise exception 'Immutable legacy history' using errcode='23514'; end if;
    for discriminator in select value from jsonb_array_elements(d->'markerlessV2Discriminators') loop
      v:=b #> string_to_array(discriminator->>'path','.');
      if (coalesce((discriminator->>'presence')::boolean,false) and v is not null) or ((not discriminator ? 'equals') and v is not null and v<>'null'::jsonb) or (discriminator ? 'equals' and v=discriminator->'equals') then raise exception 'V2 row requires protected marker' using errcode='23514'; end if;
    end loop;
    return new;
  end if;
  for equality in select value from jsonb_array_elements(d->'projectionEqualities') loop
    if (b #> string_to_array(equality->>'leftPath','.')) is distinct from (b #> string_to_array(equality->>'rightPath','.')) then raise exception 'Inconsistent workflow reference projection' using errcode='23514'; end if;
  end loop;
  if tg_table_name in ('pending_actions','action_executions') and b->>'contractVersion' is distinct from '2' then raise exception 'Protected workflow contract version required' using errcode='23514'; end if;
  if tg_table_name='pending_actions' and (b #>> '{policy,id}' is null or b #>> '{policy,version}' is null or b #>> '{policy,digest}' is null) then raise exception 'Missing workflow policy reference' using errcode='23514'; end if;
  if tg_op='INSERT' then
    if d->>'storage'='shared' and new.row_version is null then new.row_version:=1; end if;
    if new.row_version is distinct from 1 then raise exception 'Invalid workflow insertion version' using errcode='23514'; end if;
  else
    if d->>'storage'='shared' and new.row_version=old.row_version then new.row_version:=old.row_version+1; end if;
    if new.row_version is distinct from old.row_version+1 then raise exception 'Invalid workflow conditional version' using errcode='23514'; end if;
    for field in select jsonb_array_elements_text(d->'immutableFields') loop
      if b #> string_to_array(field,'.') is distinct from old_b #> string_to_array(field,'.') then raise exception 'Immutable workflow field' using errcode='23514'; end if;
    end loop;
    if exists(select 1 from jsonb_array_elements(d->'foreignKeys') x where x ? 'tagField') and b->'ref' is distinct from old_b->'ref' then raise exception 'Immutable workflow target reference' using errcode='23514'; end if;
    if coalesce((d->>'appendOnly')::boolean,false) and b is distinct from old_b then raise exception 'Append-only workflow history' using errcode='23514'; end if;
    if tg_table_name='pending_actions' and (b-'status'-'rowVersion') is distinct from (old_b-'status'-'rowVersion') then raise exception 'Immutable workflow approval' using errcode='23514'; end if;
    old_state:=nexus_private.workflow_state(old_b,d); new_state:=nexus_private.workflow_state(b,d);
    for field in select jsonb_array_elements_text(coalesce(d->'terminalImmutableFields'->old_state,'[]'::jsonb)) loop
      if b #> string_to_array(field,'.') is distinct from old_b #> string_to_array(field,'.') then raise exception 'Immutable terminal workflow field' using errcode='23514'; end if;
    end loop;
    if tg_table_name='action_executions' and old_state in ('verified_success','already_completed','failed','denied','stale') and b is distinct from old_b then raise exception 'Immutable historical receipt' using errcode='23514'; end if;
    if tg_table_name='action_targets' and old_state in ('verified','failed') and b is distinct from old_b then raise exception 'Immutable target proof' using errcode='23514'; end if;
    if old_state is distinct from new_state and d->'permittedTransitions'<>'{}'::jsonb and not coalesce((d->'permittedTransitions'->old_state) ? new_state,false) then
      if tg_table_name<>'incidents' or not exists(select 1 from public.action_executions r join public.pending_actions a on a.id=r.payload->>'actionId' join public.profiles p on p.id=a.payload->>'actorId' join public.sessions s on s.id=a.payload->>'sessionId' where r.workflow_contract_version is null and a.workflow_contract_version is null and b->>'operationKey'=r.id||':artifact' and r.payload->>'kind'='demo_update' and r.payload->>'status'='pending' and a.payload #>> '{payload,scenario}'='baseline' and a.payload->>'status'='claimed' and p.payload->>'active'='true' and s.profile_id=p.id and (p.payload->'permissions') ? 'demo.update') then raise exception 'Invalid workflow transition' using errcode='23514'; end if;
    end if;
  end if;
  if b ? 'rowVersion' and (jsonb_typeof(b->'rowVersion')<>'number' or b->>'rowVersion' !~ '^[0-9]+$' or (b->>'rowVersion')::bigint<>new.row_version) then raise exception 'Inconsistent workflow body version' using errcode='23514'; end if;
  if d->>'storage'<>'shared' and exists(select 1 from jsonb_object_keys(b) k where not (d->'bodyFields') ? k) then raise exception 'Unsupported workflow body field' using errcode='23514'; end if;
  for child in select value from jsonb_array_elements(d->'normalizedChildren') loop
    v:=b #> string_to_array(child->>'arrayBodyField','.');
    if jsonb_typeof(v) is distinct from 'array' then raise exception 'Invalid normalized workflow scope' using errcode='23514'; end if;
    if exists(select 1 from jsonb_array_elements(v) x where jsonb_typeof(x)<>'string') or (select count(*) from jsonb_array_elements(v))<>(select count(distinct value) from jsonb_array_elements(v)) then raise exception 'Invalid normalized workflow scope' using errcode='23514'; end if;
  end loop;
  for c in select value from jsonb_array_elements(d->'columns') loop
    if coalesce((c->>'external')::boolean,false) then
      v:=row_json->(c->>'column');
      if tg_op='UPDATE' and v is distinct from to_jsonb(old)->(c->>'column') then raise exception 'Immutable workflow key projection' using errcode='23514'; end if;
    else v:=nexus_private.workflow_value(b,c); end if;
    if v='null'::jsonb then
      if not (c->>'nullable')::boolean then raise exception 'Missing workflow typed field' using errcode='23514'; end if;
    elsif (c->>'type'='text' and jsonb_typeof(v)<>'string') or (c->>'type'='boolean' and jsonb_typeof(v)<>'boolean')
      or (c->>'type' in ('integer','real') and jsonb_typeof(v)<>'number') then raise exception 'Invalid workflow typed field' using errcode='23514'; end if;
    if c->>'type'='integer' and v<>'null'::jsonb and (v::text !~ '^[0-9]+$') then raise exception 'Invalid workflow integral value' using errcode='23514'; end if;
    if c->>'type'='integer' and v<>'null'::jsonb and c->>'column' ~ '(version|attempt|quantity)$' and v::text='0' then raise exception 'Invalid workflow positive value' using errcode='23514'; end if;
    -- Explicit column tampering is rejected; omitted/stale legacy projections are derived.
    if row_json->(c->>'column') is not null and row_json->(c->>'column')<>'null'::jsonb
      and row_json->(c->>'column') is distinct from v
      and (tg_op='INSERT' or row_json->(c->>'column') is distinct from to_jsonb(old)->(c->>'column')) then raise exception 'Inconsistent workflow SQL projection' using errcode='23514'; end if;
    typed:=typed||jsonb_build_object(c->>'column',v);
  end loop;
  new:=jsonb_populate_record(new,typed);
  new_state:=nexus_private.workflow_state(b,d);
  if d->'permittedTransitions'<>'{}'::jsonb and (new_state is null or not (d->'permittedTransitions') ? new_state) then raise exception 'Invalid workflow status' using errcode='23514'; end if;
  for f in select value from jsonb_array_elements(d->'foreignKeys') where value ? 'tagField' loop
    if (to_jsonb(new)->(f->>'column'))<>'null'::jsonb then target_count:=target_count+1; end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(d->'foreignKeys') x where x ? 'tagField') then
    if target_count<>1 or b->>'entityType' is distinct from b #>> '{ref,table}' then raise exception 'Invalid workflow target reference' using errcode='23514'; end if;
  end if;
  if tg_table_name='share_scope_branches' and not exists(select 1 from public.dashboard_shares s,jsonb_array_elements_text(s.payload->'approvedBranchIds') x where s.id=b->>'shareId' and s.workflow_contract_version=2 and x=b->>'branchId') then raise exception 'Invalid workflow relationship' using errcode='23514'; end if;
  if tg_table_name='onboarding_requests' then
    foreach field in array array['manager','director'] loop
      v:=b->(field||'ApprovalEventId');
      if (v is null or v='null'::jsonb) then
        if (field='manager' and b->>'state' in ('director_approval_pending','director_approved','onboarding_in_progress','completed')) or (field='director' and b->>'state' in ('director_approved','onboarding_in_progress','completed')) then raise exception 'Missing onboarding approval proof' using errcode='23514'; end if;
      elsif not exists(select 1 from public.onboarding_approval_events e where e.id=b->>(field||'ApprovalEventId') and e.request_id=new.id and e.stage=field and e.lifecycle_id=b->>'lifecycleId' and e.actor_identity_id=b->>(field||'IdentityId')) then raise exception 'Invalid onboarding approval proof' using errcode='23514'; end if;
    end loop;
  end if;
  if tg_table_name='action_idempotency_roots' and exists(select 1 from public.action_executions e where e.id=b->>'activeExecutionId' and e.workflow_contract_version=2 and e.root_id<>new.id) then raise exception 'Invalid workflow execution root' using errcode='23514'; end if;
  if tg_table_name='action_executions' and exists(select 1 from public.action_idempotency_roots r where r.active_execution_id=new.id and r.id<>(to_jsonb(new)->>'root_id')) then raise exception 'Invalid workflow execution root' using errcode='23514'; end if;
  if tg_table_name='policy_acknowledgement_tasks' and not exists(select 1 from public.policy_documents p where p.id=b->>'policyDocumentId' and p.version=b->>'policyVersion') then raise exception 'Invalid workflow policy reference' using errcode='23514'; end if;
  if tg_table_name='simulated_deliveries' and not exists(select 1 from public.dashboard_shares s where s.id=b->>'shareId' and s.workflow_contract_version=2 and s.recipient_identity_id=b->>'recipientIdentityId' and s.payload->>'channel'=b->>'channel' and s.execution_id=b->>'executionId') then raise exception 'Invalid workflow delivery reference' using errcode='23514'; end if;
  return new;
end $$;

create or replace function nexus_private.workflow_revision() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  update public.appmeta set revision=revision+1 where singleton=1 and workflow_adapter_write=0;
  return null;
end $$;

create or replace function nexus_private.workflow_children() returns trigger
language plpgsql security definer set search_path='' as $$
declare d jsonb; child jsonb; b jsonb;
begin
  select definition into strict d from nexus_private.workflow_manifest where table_name=tg_table_name;
  b:=to_jsonb(new)->(d->>'bodyColumn');
  for child in select value from jsonb_array_elements(d->'normalizedChildren') loop
    execute format('delete from public.%I where %I=$1 and %I not in(select value from jsonb_array_elements_text($2))',child->>'table',child->>'parentIdColumn',child->>'childIdColumn') using new.id,b #> string_to_array(child->>'arrayBodyField','.');
    execute format('insert into public.%I(%I,%I) select $1,value from jsonb_array_elements_text($2) on conflict do nothing',child->>'table',child->>'parentIdColumn',child->>'childIdColumn') using new.id,b #> string_to_array(child->>'arrayBodyField','.');
  end loop;
  return null;
end $$;

create or replace function nexus_private.workflow_child_guard() returns trigger
language plpgsql security definer set search_path='' as $$
declare d jsonb; child jsonb; present boolean; row_data jsonb; parent_id text; target_id text;
begin
  select m.definition,x.value into strict d,child from nexus_private.workflow_manifest m cross join lateral jsonb_array_elements(m.definition->'normalizedChildren') x where x.value->>'table'=tg_table_name;
  row_data:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  parent_id:=row_data->>(child->>'parentIdColumn');target_id:=row_data->>(child->>'childIdColumn');
  execute format('select exists(select 1 from public.%I p,jsonb_array_elements_text(p.%I #> $3::text[]) x where p.id=$1 and x.value=$2)',d->>'table',d->>'bodyColumn') into present using parent_id,target_id,string_to_array(child->>'arrayBodyField','.');
  if (tg_op='DELETE' and present) or (tg_op<>'DELETE' and not present) then raise exception 'Scope projection must follow parent' using errcode='23514'; end if;
  if tg_op='UPDATE' and row_data is distinct from to_jsonb(old) then raise exception 'Scope projection must follow parent' using errcode='23514'; end if;
  if tg_op='DELETE' then return old; end if;return new;
end $$;

do $$
declare d jsonb; child jsonb; tbl text;
begin
  for d in select definition from nexus_private.workflow_manifest loop
    tbl:=d->>'table';
    execute format('drop trigger if exists nexus_revision on public.%I',tbl);
    execute format('drop trigger if exists workflow_guard on public.%I',tbl);
    execute format('create trigger workflow_guard before insert or update or delete on public.%I for each row execute function nexus_private.workflow_guard()',tbl);
    execute format('create trigger nexus_revision before insert or update or delete or truncate on public.%I for each statement execute function nexus_private.workflow_revision()',tbl);
    execute format('drop trigger if exists workflow_children on public.%I',tbl);
    if jsonb_array_length(d->'normalizedChildren')>0 then execute format('create trigger workflow_children after insert or update on public.%I for each row execute function nexus_private.workflow_children()',tbl); end if;
    for child in select value from jsonb_array_elements(d->'normalizedChildren') loop
      execute format('drop trigger if exists workflow_child_guard on public.%I',child->>'table');
      execute format('create trigger workflow_child_guard before insert or update or delete on public.%I for each row execute function nexus_private.workflow_child_guard()',child->>'table');
      execute format('drop trigger if exists nexus_revision on public.%I',child->>'table');
      execute format('create trigger nexus_revision before insert or update or delete or truncate on public.%I for each statement execute function nexus_private.workflow_revision()',child->>'table');
    end loop;
  end loop;
end $$;

create or replace function public.nexus_workflow_commit(expected_revision bigint, operations jsonb) returns bigint
language plpgsql security definer set search_path='' as $$
declare actual bigint; op jsonb; d jsonb; r jsonb; b jsonb; tbl text; names text; vals text;
  criterion text; u jsonb; c jsonb; v jsonb; field text; colname text; current_body jsonb; affected bigint; row_data jsonb;
begin
  if expected_revision is null or expected_revision<0 or operations is null or jsonb_typeof(operations)<>'array'
    or jsonb_array_length(operations)>50000 or octet_length(operations::text)>20971520 then raise exception 'Invalid workflow commit batch' using errcode='22023'; end if;
  select revision into actual from public.appmeta where singleton=1 for update;
  if actual is distinct from expected_revision then raise exception 'Workflow revision conflict' using errcode='40001'; end if;
  update public.appmeta set workflow_adapter_write=1 where singleton=1;
  for op in select value from jsonb_array_elements(operations) loop
    tbl:=op->>'table';
    select definition into d from nexus_private.workflow_manifest where table_name=tbl;
    if d is null or jsonb_typeof(op)<>'object' or op->>'kind' is null or op->>'kind' not in ('insert_unique','cas') then raise exception 'Invalid workflow operation' using errcode='22023'; end if;
    if (op->>'kind'='insert_unique' and (not op ?& array['kind','table','constraint','values','row'] or (select count(*) from jsonb_object_keys(op))<>5))
      or (op->>'kind'='cas' and (not op ?& array['kind','table','id','expected','next'] or (select count(*) from jsonb_object_keys(op))<>5)) then raise exception 'Invalid workflow operation fields' using errcode='22023'; end if;
    r:=case when op->>'kind'='cas' then op->'next' else op->'row' end; b:=r->'body';
    if jsonb_typeof(r)<>'object' or not r ?& array['id','rowVersion','body'] or (select count(*) from jsonb_object_keys(r))<>3 or jsonb_typeof(b)<>'object' or r->>'id' is distinct from b->>'id'
      or jsonb_typeof(r->'id')<>'string' or r->>'id' is null or length(r->>'id')>300 or jsonb_typeof(r->'rowVersion')<>'number' or r->>'rowVersion' !~ '^[1-9][0-9]*$' then raise exception 'Invalid workflow operation row' using errcode='22023'; end if;
    row_data:=jsonb_build_object('id',r->>'id','row_version',(r->>'rowVersion')::bigint,d->>'bodyColumn',b);
    names:='id,row_version,'||format('%I',d->>'bodyColumn'); vals:='x.id,x.row_version,x.'||format('%I',d->>'bodyColumn');
    if d->>'storage'='mixed' then row_data:=row_data||jsonb_build_object('workflow_contract_version',2); names:=names||',workflow_contract_version';vals:=vals||',x.workflow_contract_version'; end if;
    for c in select value from jsonb_array_elements(d->'columns') loop
      if coalesce((c->>'external')::boolean,false) then
        if op->>'kind'='insert_unique' then
          if op->>'constraint'<>'action_executions_root_attempt_unique' or tbl<>'action_executions' then raise exception 'Invalid external workflow key' using errcode='22023'; end if;
          v:=op->'values'->(c->>'bodyField');
        else execute format('select to_jsonb(t)->%L from public.%I t where id=$1',c->>'column',tbl) into v using r->>'id'; end if;
      else v:=nexus_private.workflow_value(b,c); end if;
      row_data:=row_data||jsonb_build_object(c->>'column',v);
      names:=names||','||format('%I',c->>'column');vals:=vals||',x.'||format('%I',c->>'column');
    end loop;
    if op->>'kind'='insert_unique' then
      if op->>'constraint'=tbl||'_primary_key' then u:=jsonb_build_object('fields',jsonb_build_array('id'));
      else select value into u from jsonb_array_elements(d->'unique') where value->>'name'=op->>'constraint'; end if;
      if u is null or jsonb_typeof(op->'values')<>'object' or (select count(*) from jsonb_object_keys(op->'values'))<>jsonb_array_length(u->'fields') then raise exception 'Invalid workflow unique constraint' using errcode='22023'; end if;
      criterion:='';
      for field in select jsonb_array_elements_text(u->'fields') loop
        select x into c from jsonb_array_elements(d->'columns') x where x->>'bodyField'=field;
        if not (op->'values') ? field or (not coalesce((c->>'external')::boolean,false) and (op->'values'->field) is distinct from (b #> string_to_array(field,'.'))) then raise exception 'Invalid workflow unique key' using errcode='22023'; end if;
        if field='id' then colname:='id'; else select x->>'column' into colname from jsonb_array_elements(d->'columns') x where x->>'bodyField'=field; end if;
        if colname is null then raise exception 'Invalid workflow unique field' using errcode='22023'; end if;
        criterion:=criterion||case when criterion='' then '' else ' and ' end||format('to_jsonb(t)->%L = $1->%L',colname,field);
      end loop;
      if d->>'storage'='mixed' then criterion:=criterion||' and t.workflow_contract_version=2'; end if;
      if coalesce((u->>'openOnly')::boolean,false) then
        select string_agg(quote_literal(value),',') into field from jsonb_array_elements_text(u->'openStates');
        if field is null then raise exception 'Invalid workflow open constraint' using errcode='22023'; end if;
        criterion:=criterion||format(' and nexus_private.workflow_state(t.%I,%L::jsonb) in (%s)',d->>'bodyColumn',d::text,field);
      end if;
      execute format('select t.%I from public.%I t where %s limit 1',d->>'bodyColumn',tbl,criterion) into current_body using op->'values';
      if current_body is not null then
        if current_body is distinct from b then raise exception 'Workflow unique operation conflict' using errcode='23505'; end if;
      else
        execute format('insert into public.%I(%s) select %s from jsonb_populate_record(null::public.%I,$1) x',tbl,names,vals,tbl) using row_data;
      end if;
    else
      if jsonb_typeof(op->'expected')<>'object' or not (op->'expected') ?& array['rowVersion','state'] or (select count(*) from jsonb_object_keys(op->'expected'))<>2
        or jsonb_typeof(op #> '{expected,rowVersion}')<>'number' or jsonb_typeof(op #> '{expected,state}') not in ('string','null')
        or op->>'id' is distinct from r->>'id' or op #>> '{expected,rowVersion}' !~ '^[1-9][0-9]*$'
        or (r->>'rowVersion')::bigint<>(op #>> '{expected,rowVersion}')::bigint+1 then raise exception 'Invalid workflow CAS version' using errcode='22023'; end if;
      criterion:=format('t.id=$2 and t.row_version=$3 and nexus_private.workflow_state(t.%I,%L::jsonb) is not distinct from $4',d->>'bodyColumn',d::text);
      if d->>'storage'='mixed' then criterion:=criterion||' and t.workflow_contract_version=2'; end if;
      names:='';
      for colname in select key from jsonb_each(row_data) where key<>'id' loop names:=names||case when names='' then '' else ',' end||format('%I=x.%I',colname,colname); end loop;
      execute format('update public.%I t set %s from jsonb_populate_record(null::public.%I,$1) x where %s',tbl,names,tbl,criterion)
        using row_data,r->>'id',(op #>> '{expected,rowVersion}')::bigint,op #>> '{expected,state}';
      get diagnostics affected=row_count;
      if affected<>1 then raise exception 'Workflow conditional conflict' using errcode='40001'; end if;
    end if;
  end loop;
  update public.appmeta set revision=actual+1,workflow_adapter_write=0 where singleton=1;
  return actual+1;
end $$;

-- Legacy calls retain their wire signature and table allowlist but cannot mutate V2 rows.
create or replace function public.nexus_commit(expected_revision bigint, changes jsonb) returns bigint
language plpgsql security invoker set search_path='' as $$
declare actual bigint; entry jsonb; target text; row_id text; body jsonb; protected integer; definition jsonb;
begin
  if expected_revision is null or jsonb_typeof(changes)<>'array' or jsonb_array_length(changes)>50000 or octet_length(changes::text)>20971520 then raise exception 'Invalid commit batch' using errcode='22023'; end if;
  select revision into actual from public.appmeta where singleton=1 for update;
  if actual is distinct from expected_revision then raise exception 'Revision conflict' using errcode='40001'; end if;
  for entry in select value from jsonb_array_elements(changes) loop
    target:=entry->>'table';row_id:=entry->>'id';body:=entry->'payload';
    if target is null or target<>all(array['profiles','branches','products','sales_orders','sales_targets','inventory_snapshots','incidents','staffing_summaries','employees','policy_documents','sessions','conversations','conversation_messages','tool_executions','dashboards','dashboard_shares','pending_actions','action_executions','audit_events','mock_tickets','mock_badges','mock_messages','rate_limits']) or row_id is null or length(row_id)>300 then raise exception 'Invalid commit target' using errcode='22023'; end if;
    if target in ('mock_tickets','pending_actions','action_executions','dashboard_shares','audit_events') then
      execute format('select workflow_contract_version from public.%I where id=$1',target) into protected using row_id;
      if protected=2 or body->>'contractVersion'='2' or (target='dashboard_shares' and body ? 'senderIdentityId') then raise exception 'Legacy mutation cannot write V2 workflow row' using errcode='23514'; end if;
    end if;
    if body='null'::jsonb then execute format('delete from public.%I where id=$1',target) using row_id;
    else
      if jsonb_typeof(body)<>'object' or body->>'id' is distinct from row_id then raise exception 'Invalid record' using errcode='22023'; end if;
      execute format('insert into public.%I(id,payload) values($1,$2) on conflict(id) do update set payload=excluded.payload',target) using row_id,body;
    end if;
  end loop;
  select revision into actual from public.appmeta where singleton=1;return actual;
end $$;

revoke all on function nexus_private.workflow_value(jsonb,jsonb), nexus_private.workflow_state(jsonb,jsonb), nexus_private.workflow_guard(), nexus_private.workflow_revision(), nexus_private.workflow_children(), nexus_private.workflow_child_guard() from public,anon,authenticated;
grant execute on function nexus_private.workflow_state(jsonb,jsonb) to service_role;
revoke all on function public.nexus_workflow_commit(bigint,jsonb) from public,anon,authenticated;
grant execute on function public.nexus_workflow_commit(bigint,jsonb) to service_role;
revoke all on function public.nexus_commit(bigint,jsonb) from public,anon,authenticated;
grant execute on function public.nexus_commit(bigint,jsonb) to service_role;
commit;
